    (if (== head-off 0)
      0
      (i32 (- (long (utfc-ptr2len ed (.add p (- head-off)))) head-off)))))

;; C: mb_prevptr
(defn mb-prevptr ^BytePtr [^Editor ed ^BytePtr line ^BytePtr p]
